-- Postgres full-text search with GIN inverted index
CREATE INDEX idx_articles_fts
    ON articles USING GIN (to_tsvector('english', body));

SELECT title
FROM   articles
WHERE  to_tsvector('english', body) @@ to_tsquery('english', 'b-tree & lsm');

-- GIN = Generalised Inverted Index; also used for JSONB, arrays, hstore
CREATE INDEX idx_tags ON posts USING GIN (tags);  -- tags is text[]
SELECT * FROM posts WHERE tags @> '{postgres,indexing}';
